private static boolean rename(SmallHouseBlockEntity blockEntity, String value) {
    String name;
    String string = name = value == null ? "" : value.trim();
    if (name.length() > 64) {
        name = name.substring(0, 64);
    }
    if (name.equals(blockEntity.displayName())) {
        return false;
    }
    blockEntity.setDisplayName(name);
    return true;
}

private static boolean setSettings(ServerPlayer player, PlayerCompanionData data, FindMeWorldSavedData world, FindMeWorldSavedData.HouseRecord house, String value) {
    String[] parts;
    String[] stringArray = parts = value == null ? new String[]{} : value.split(",", -1);
    if (parts.length != 3) {
        return false;
    }
    try {
        int capacity = Integer.parseInt(parts[0].trim());
        int patrolRadius = Integer.parseInt(parts[1].trim());
        int hardRadius = Integer.parseInt(parts[2].trim());
        boolean changed = world.setHouseSettings(house.houseId(), capacity, patrolRadius, hardRadius);
        if (changed) {
            FindMeWorldSavedData.HouseRecord updated = world.house(house.houseId()).orElse(house);
            for (UUID resident : updated.residents()) {
                CompanionHomeResidentService.refreshResidentMode(player, data, resident, updated.residentMode(resident));
            }
        }
        return changed;
    }
    catch (NumberFormatException ignored) {
        return false;
    }
}

static boolean withinInteractionDistance(boolean sameDimension, double playerX, double playerY, double playerZ, SavedPosition housePosition) {
    double dz;
    double dy;
    if (!sameDimension || housePosition == null) {
        return false;
    }
    double dx = playerX - (housePosition.x() + 0.5);
    return dx * dx + (dy = playerY - (housePosition.y() + 0.5)) * dy + (dz = playerZ - (housePosition.z() + 0.5)) * dz <= 64.0;
}

private static boolean setResidentMode(ServerPlayer player, PlayerCompanionData data, FindMeWorldSavedData world, FindMeWorldSavedData.HouseRecord house, UUID uuid, String value) {
    HouseResidentMode mode;
    if (uuid == null || !HousePageService.houseResidents(data, house).contains(uuid)) {
        return false;
